#include <bits/stdc++.h>
using namespace std; using ll=long long; using U=uint64_t;
void req(bool b,const char*m){if(!b)throw runtime_error(m);}
U key(int a,int b){if(a>b)swap(a,b);return (U(unsigned(a))<<32)|unsigned(b);}
struct G{int r,p;vector<int>x;ll alo=0;};
int main(int argc,char**argv){try{
req(argc==4,"usage");ifstream cert(argv[2]);string magic;int a,b,n;req(bool(cert>>magic>>a>>b>>n)&&magic=="ENERGY20"&&a>=0&&b>a&&b<=4096&&n>=2&&n<=256,"cert");vector<G> gs(n);map<int,int> owner,weights;vector<vector<int>> starts(b-a),ends(b-a+1);ll demand=0;
for(int u=0;u<n;u++){auto&g=gs[u];int k;req(bool(cert>>g.r>>g.p>>k)&&g.r>=0&&g.p>0&&k>0&&k<=4096,"group");int m=b-a;for(int i=0;i<k;i++){int x;req(bool(cert>>x)&&x>0&&owner.emplace(x,u).second,"selector");g.x.push_back(x);int l=max(a,g.r+i),r=min(b,g.r+i+g.p);int w=max(0,r-l);weights[x]=w;m=min(m,w);if(w){starts[l-a].push_back(x);ends[r-a].push_back(x);}}demand+=m;}req(demand>b-a,"no overload");req(!(cert>>magic),"trailing cert");
ifstream f(argv[1]);req(bool(f),"source open");string line;int nv=0;ll nc=0,id=0;bool header=false;vector<int> cl;unordered_map<U,ll> mutex;unordered_map<int,vector<pair<int,ll>>> impl;mutex.reserve(2000000);
while(getline(f,line)){if(line.empty()||line[0]=='c')continue;if(line[0]=='p'){istringstream s(line);string p,cnf;req(!header&&bool(s>>p>>cnf>>nv>>nc)&&cnf=="cnf","header");header=true;continue;}req(header,"header missing");const char*s=line.c_str();char*end;while(*s){while(isspace((unsigned char)*s))s++;if(!*s)break;long v=strtol(s,&end,10);req(end!=s&&v>=-nv&&v<=nv,"literal");s=end;if(v){cl.push_back(v);continue;}++id;if(cl.size()==2){int x=cl[0],y=cl[1];if(x<0&&y<0&&owner.count(-x)&&owner.count(-y)&&x!=y)mutex.emplace(key(-x,-y),id);if(x<0&&owner.count(-x)&&!owner.count(abs(y)))impl[-x].emplace_back(y,id);if(y<0&&owner.count(-y)&&!owner.count(abs(x)))impl[-y].emplace_back(x,id);}
if(!cl.empty()&&owner.count(cl[0])){auto&g=gs[owner.at(cl[0])];if(!g.alo&&cl.size()==g.x.size()){auto z=cl,q=g.x;sort(z.begin(),z.end());sort(q.begin(),q.end());if(z==q)g.alo=id;}}cl.clear();}}
req(header&&id==nc&&cl.empty(),"clause count");for(auto&g:gs)req(g.alo>0,"missing ALO");
ofstream out(argv[3]);req(bool(out),"proof open");out<<"pseudo-Boolean proof version 3.0\nf "<<nc<<" ;\n";ll steps=0,derived_pairs=0;auto finish=[&](){out<<" ;\n";++steps;return ++id;};
auto edge=[&](int x,int y){U k=key(x,y);auto it=mutex.find(k);if(it!=mutex.end())return it->second;req(owner.at(x)==owner.at(y),"missing cross mutex");for(auto [l,i]:impl[x])for(auto [m,j]:impl[y])if(l==-m){out<<"pol "<<i<<' '<<j<<" +";ll h=finish();mutex.emplace(k,h);++derived_pairs;return h;}throw runtime_error("unsupported same-group AMO");};
set<int> active;ll amo=0;vector<ll> caps;for(int t=0;t<b-a;t++){if(!ends[t].empty()){if(amo&&active.size()-ends[t].size()>=2){out<<"pol "<<amo;for(int x:ends[t])out<<" x"<<x<<" w";amo=finish();}else amo=0;for(int x:ends[t])req(active.erase(x)==1,"remove inactive");}
for(int x:starts[t]){if(active.size()==1)amo=edge(*active.begin(),x);else if(active.size()>=2){vector<ll> es;for(int y:active)es.push_back(edge(x,y));out<<"pol "<<amo<<' '<<active.size()-1<<" *";for(ll e:es)out<<' '<<e<<" +";out<<' '<<active.size()<<" d";amo=finish();}active.insert(x);}if(active.size()>=2)caps.push_back(amo);else if(active.size()==1){out<<"pol ~x"<<*active.begin();caps.push_back(finish());}}
vector<ll> ds;for(auto&g:gs){int m=b-a;for(int x:g.x)m=min(m,weights.at(x));if(!m){bool first=true;for(int x:g.x)if(weights[x]){if(first){out<<"pol x"<<x<<' '<<weights[x]<<" *";first=false;}else out<<" x"<<x<<' '<<weights[x]<<" * +";}if(!first)ds.push_back(finish());continue;}out<<"pol "<<g.alo<<' '<<m<<" *";for(int x:g.x)if(weights[x]>m)out<<" x"<<x<<' '<<weights[x]-m<<" * +";ds.push_back(finish());}
req(!ds.empty(),"no demand");out<<"pol "<<ds[0];for(size_t j=1;j<ds.size();j++)out<<' '<<ds[j]<<" +";for(ll c:caps)out<<' '<<c<<" +";finish();out<<"output NONE ;\nconclusion UNSAT ;\nend pseudo-Boolean proof ;\n";req(bool(out),"write proof");cerr<<"EMITTED_UNCHECKED steps="<<steps<<" derived_pairs="<<derived_pairs<<" demand="<<demand<<" capacity="<<b-a<<'\n';return 0;
}catch(exception&e){cerr<<"REJECTED "<<e.what()<<'\n';return 1;}}
